#!/usr/bin/env node
'use strict';

import { readFile } from 'node:fs/promises';
import path from 'node:path';

const DEFAULTS = { retries: 3, verbose: false };

/**
 * Loads a config file and merges defaults.
 */
export async function loadConfig(file, options = {}) {
  const text = await readFile(path.resolve(file), 'utf8');
  const { retries = DEFAULTS.retries, ...rest } = JSON.parse(text);
  return { ...DEFAULTS, ...rest, retries };
}

class Cache {
  #store = new Map();
  static instances = 0;

  constructor(limit = 10) {
    this.limit = limit;
    Cache.instances += 1;
  }

  get(key) {
    return this.#store.get(key) ?? null;
  }

  set(key, value) {
    if (this.#store.size >= this.limit) {
      const [first] = this.#store.keys();
      this.#store.delete(first);
    }
    this.#store.set(key, value);
    return this;
  }
}

export const cache = new Cache(2 ** 4);

for (const [k, v] of Object.entries(DEFAULTS)) {
  console.log(`${k} -> ${v}`, /^\d+$/u.test(String(v)));
}

export default cache;

const items = [1, 2, 3];

function sum(list) {
  let total = 0;
  for (const n of list) {
    total += n;
  }
  return total;
}

console.log(sum(items));
